// A song's credits from YouTube, the fallback when Apple Music had nothing (the owner's research, 2026-11-17: 5 of 10 real placements, none wrong). A song
// a distributor delivers gets an auto-generated "Topic" video whose description begins "Provided to YouTube by <label>" and lists the credits:
//     Provided to YouTube by DistroKid
//     Givenchy Coat · RRoxket · RRoxket Montana · Prod. Chxse · Prod. Midtwos        (the title, then everyone named on the release: "Prod. X" is a producer)
//     Producer: Stack!e / Composer, Lyricist: Aubrey Graham                         (the other distributors list one credit a line, its roles before the colon)
// The official YouTube Data API is used (YOUTUBE_API_KEY, the key lib/data/direct.js already reads for channel stats): a search for "<artist> <title>" costs 100
// units and is made only when Apple had nothing (30 a day at most, 3,000 of the free 10,000 units), then videos.list reads the full descriptions of what it found
// (1 unit; the search's own snippet cuts them short). Only an auto-generated description whose title, artist and length are the track's is read: an artist's
// own upload, with a producer typed into its description by hand, is not. Nothing is written anywhere from here. Server-only.
import { titleParts, artistNames } from "../isrc";
import { clean } from "./http";
import { isCredit, stripProd } from "./match";
import { isoSeconds, LENGTH_SLOP_S } from "./apple";

export const SEARCHES_PER_DAY = 30;
export const MAX_TRIES_PER_TRACK = 5; // a search a day for a song that is on no Topic video yet would use the day's 30 on the same few

// a line "Label: …" that isn't a credit
const NOT_A_CREDIT = /^(released on|release date|℗|©|copyright|label|music publisher|publisher|source|isrc|upc|recorded at|provided to youtube by|auto-generated by youtube|http|www)/i;
const ROLE_SPLIT = /\s*[,&\/]\s*|\s+and\s+/i;
const NAME_SPLIT = /\s*[,;&\/]\s*|\s+(?:and|feat\.?|ft\.?)\s+/i;

// An auto-generated description -> { ok: true, title, artists, label, releasedOn, credits: [{ name, roles }] }, or { ok: false, why }.
// The credits are everyone it names: the release line's artists (role "Artist"), its "Prod. X" names (role "Producer"), and each "Roles: Name, Name" line.
export function parseDescription(desc) {
  const text = String(desc ?? "").replace(/\r\n?/g, "\n");
  const head = /^\s*Provided to YouTube by\s+(.+)/i.exec(text);
  if (!head) return { ok: false, why: "not an auto-generated description" };
  const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);
  const credits = [], artists = [];
  let title = "";
  const dot = lines.slice(1).find((l) => l.includes(" · "));
  if (dot) {
    const parts = dot.split(" · ").map((x) => x.trim()).filter(Boolean);
    title = parts[0] || "";
    for (const name of parts.slice(1)) {
      if (stripProd(name)) credits.push({ name, roles: ["Producer"] });
      else { artists.push(name); credits.push({ name, roles: ["Artist"] }); }
    }
  }
  let releasedOn = "";
  for (const line of lines.slice(1)) {
    if (line === dot) continue;
    const m = /^([^:·]{2,70}):\s*(.+)$/.exec(line);
    if (!m) continue;
    const label = m[1].trim();
    if (/^released on$/i.test(label)) { releasedOn = m[2].trim(); continue; }
    if (NOT_A_CREDIT.test(label)) continue;
    const roles = label.split(ROLE_SPLIT).map((r) => r.trim()).filter(Boolean);
    for (const name of m[2].split(NAME_SPLIT).map((n) => n.trim()).filter(Boolean)) credits.push({ name, roles });
  }
  return { ok: true, title, artists, label: head[1].trim(), releasedOn, credits };
}

// a 4xx that means "stop for today" (the quota, a key YouTube won't take): the reason, else ""
const stopFor = (r) => {
  if (r.ok || ![400, 401, 403].includes(r.status)) return "";
  const why = String(r.body?.error?.errors?.[0]?.reason || r.body?.error?.status || "").slice(0, 60);
  return /quota|limit/i.test(why) ? "YouTube's daily quota is used up" : `YouTube refused the request (${r.status}${why ? ` ${why}` : ""})`;
};

// One track's credits from YouTube. t: the track's state (name, artist, ms); day.youtube: today's { searches, stop }; key: YOUTUBE_API_KEY.
// -> { status, ... }:
//   found      { videoId, credits }   an auto-generated description of this song lists credits (someone besides the performers)
//   nocredits  { videoId }            the song's description is there and names only its artists
//   notfound   { why }                no auto-generated video of this song (yet)
//   stopped    { why, budget? }       no key, the day's searches are used, or YouTube refused (quota, key): no try is counted
//   error      { why }                a network error or a 5xx: no try is counted
export async function youtubeCredits(t, ctx, day, { key, cap = SEARCHES_PER_DAY } = {}) {
  const Y = day.youtube;
  if (!key) return { status: "stopped", why: "no YouTube key is set" };
  if (Y.stop) return { status: "stopped", why: Y.stop };
  if (Y.searches >= cap) return { status: "stopped", why: `today's ${cap} YouTube searches are used`, budget: true };
  const q = `${String(t.artist || "").split(",")[0].trim()} ${t.name}`.trim();
  const base = "https://www.googleapis.com/youtube/v3";
  Y.searches++;
  let s;
  try { s = await ctx.get(`${base}/search?part=snippet&type=video&videoCategoryId=10&maxResults=5&q=${encodeURIComponent(q)}&key=${encodeURIComponent(key)}`, { host: "www.googleapis.com" }); } catch (err) { return { status: "error", why: clean(err) }; }
  const bad = stopFor(s);
  if (bad) { Y.stop = bad; return { status: "stopped", why: bad }; }
  if (!s.ok) return { status: "error", why: `YouTube search answered ${s.status}` };
  const ids = (s.body?.items || []).map((i) => i?.id?.videoId).filter((x) => /^[\w-]{11}$/.test(x || ""));
  if (!ids.length) return { status: "notfound", why: "no YouTube video for it yet" };
  let v;
  try { v = await ctx.get(`${base}/videos?part=snippet,contentDetails&id=${ids.join(",")}&key=${encodeURIComponent(key)}`, { host: "www.googleapis.com" }); } catch (err) { return { status: "error", why: clean(err) }; }
  const bad2 = stopFor(v);
  if (bad2) { Y.stop = bad2; return { status: "stopped", why: bad2 }; }
  if (!v.ok) return { status: "error", why: `YouTube videos answered ${v.status}` };
  const want = { t: titleParts(t.name), names: artistNames(t.artist) };
  for (const item of v.body?.items || []) {
    const d = parseDescription(item?.snippet?.description);
    if (!d.ok) continue;
    const a = titleParts(d.title || item.snippet?.title || ""), b = want.t;
    if (!(a.versions === b.versions && (a.core === b.core || a.bare === b.bare || a.core === b.bare || a.bare === b.core))) continue;
    const names = artistNames([...d.artists, String(item.snippet?.channelTitle || "").replace(/\s*-\s*Topic$/i, "")].join(", "));
    if (want.names.length && !names.some((n) => want.names.includes(n))) continue;
    const sec = isoSeconds(item.contentDetails?.duration);
    if (sec && t.ms && Math.abs(sec - t.ms / 1000) > LENGTH_SLOP_S) continue;
    return d.credits.some((c) => isCredit(c.roles)) ? { status: "found", videoId: item.id, credits: d.credits } : { status: "nocredits", videoId: item.id };
  }
  return { status: "notfound", why: "no auto-generated YouTube video of this song" };
}
